import nibabel as n, numpy as np
from scipy import ndimage
p=n.load('results/p_fwe_maxT.nii.gz').get_fdata(); t=n.load('results/tstat.nii.gz').get_fdata(); mean=n.load('results/mean_cope.nii.gz').get_fdata(); a=n.load('results/tstat.nii.gz');
lab,k=ndimage.label(np.isfinite(p)&(p<.05),structure=np.ones((3,3,3),bool))
for j in range(1,k+1):
 coords=np.array(np.where(lab==j)).T
 vals=t[lab==j]; ijk=coords[np.argmax(vals)]; xyz=n.affines.apply_affine(a.affine,ijk)
 print(len(coords),np.round(xyz,1),round(float(vals.max()),3),round(float(mean[lab==j].mean()),4),round(float(np.nanmin(p[lab==j])),4))
print('mask',int(np.isfinite(p).sum()),'signif',int(np.sum(p<.05)))
